(7124064, 1088882, 170281, '<td valign="top">Creative.  Good color and setup.  Excellent clarity.  Fun photo!</td>', 'Creative.  Good color and setup.  Excellent clarity.  Fun photo!', '2013-10-31 22:52:06.000000', NULL, 1),
