(7124074, 1089388, 170281, '<td valign="top">Excellent framing.  Great eye for the dramatic and use of rule of thirds.  Nice photo!</td>', 'Excellent framing.  Great eye for the dramatic and use of rule of thirds.  Nice photo!', '2013-10-31 23:03:54.000000', NULL, 1),
