(7125666, 1089280, 96751, '<td valign="top">Wonderful slingshot!!!! It is a very well done product shot but as wih many of the entries, this is only tangentially about the rubbert bands. Something a little more rustic, with a rubberband instead of the rubber tubing....</td>', 'Wonderful slingshot!!!! It is a very well done product shot but as wih many of the entries, this is only tangentially about the rubbert bands. Something a little more rustic, with a rubberband instead of the rubber tubing....', '2013-11-05 00:41:08.000000', NULL, 1),
(7125667, 1089392, 96751, '<td valign="top">YUM!!! LOVe this entry. Beautifully styled and lit.</td>', 'YUM!!! LOVe this entry. Beautifully styled and lit.', '2013-11-05 00:41:54.000000', NULL, 1),
(7125669, 1089292, 96751, '<td valign="top">Funny and clever, although the position of the rubber band is slightly off. A challenging setup</td>', 'Funny and clever, although the position of the rubber band is slightly off. A challenging setup', '2013-11-05 00:43:24.000000', NULL, 1),
(7125670, 1088781, 96751, '<td valign="top">This is remarkably beautiful, but I do not see any rubber bands. If they/it are/is there, I cannot tell.</td>', 'This is remarkably beautiful, but I do not see any rubber bands. If they/it are/is there, I cannot tell.', '2013-11-05 00:44:28.000000', NULL, 1),
(7125671, 1089221, 96751, '<td valign="top">Clever and adorable. Somehow, it looks a bit messy. Perhaps it''s the general lighting, giving everything the same weight. Also, since they are escaping, I feel that more of a "nighttime" feel would be appropriate, and perhaps some vignetting or a snoot to make it look more like a prison break.</td>', 'Clever and adorable. Somehow, it looks a bit messy. Perhaps it''s the general lighting, giving everything the same weight. Also, since they are escaping, I feel that more of a "nighttime" feel would be appropriate, and perhaps some vignetting or a snoot to make it look more like a prison break.', '2013-11-05 00:46:09.000000', NULL, 1),
(7125673, 1089347, 96751, '<td valign="top">A ribbon contender for sure. The lighting, colors, concept... top notch. Where did you find black rubber bands, or were they converted in post?  WD.</td>', 'A ribbon contender for sure. The lighting, colors, concept... top notch. Where did you find black rubber bands, or were they converted in post?  WD.', '2013-11-05 00:49:42.000000', NULL, 1),
(7125674, 1089218, 96751, '<td valign="top">A lot of rubber bands as food :-)</td>', 'A lot of rubber bands as food :-)', '2013-11-05 00:50:05.000000', NULL, 1),
(7125676, 1089304, 96751, '<td valign="top">I don''t know what to make of this image.... the model is wonderful, as is the lighting, the concept, the styling. But the little poster, the huge white background... odd.</td>', 'I don''t know what to make of this image.... the model is wonderful, as is the lighting, the concept, the styling. But the little poster, the huge white background... odd.', '2013-11-05 00:51:45.000000', NULL, 1),
(7125677, 1089169, 96751, '<td valign="top">Of the seven images of guys wearing rubber bands on their face, this might be the best. Fabulous lighting. Might even be a contender.</td>', 'Of the seven images of guys wearing rubber bands on their face, this might be the best. Fabulous lighting. Might even be a contender.', '2013-11-05 00:52:30.000000', NULL, 1),
(7125678, 1089283, 96751, '<td valign="top">I love the idea, but feel that the rubber band itself is not particularly well lit, or highlighted.</td>', 'I love the idea, but feel that the rubber band itself is not particularly well lit, or highlighted.', '2013-11-05 00:53:31.000000', NULL, 1),
(7125679, 1089214, 96751, '<td valign="top">This is so darned artistic. It is one of my favorite images of the challenge, but I don''t feel it''s a strong entry.</td>', 'This is so darned artistic. It is one of my favorite images of the challenge, but I don''t feel it''s a strong entry.', '2013-11-05 00:54:34.000000', NULL, 1),
